// features/lifecycle.feature: An admin can review vendors
import { expect, expectStatus, test } from "../../fixtures";

test("an admin can open the review queue and approve a vendor's w9 extraction", { tag: "@LIF-12" }, async ({ apiAs, factory }) => {
  // Arrange
  const admin = await apiAs("admin");
  const { vendor, documents, extractions } = await factory.vendorInReview();

  // Act
  const queueBefore = await expectStatus<{ vendor_id: string }[]>(await admin.get("/api/review-queue"), 200);
  const response = await admin.post(`/api/extractions/${extractions.w9.id}/decision`, {
    data: { decision: "approve" },
  });

  // Assert
  const decided = await expectStatus<{ id: string; status: string }>(response, 200);
  expect(decided.id).toBe(extractions.w9.id);
  expect(queueBefore.map((item) => item.vendor_id), "queue lists the vendor").toContain(vendor.id);
  const queueAfter = await expectStatus<{ vendor_id: string }[]>(await admin.get("/api/review-queue"), 200);
  expect(queueAfter.map((item) => item.vendor_id), "queue still lists the vendor").toContain(vendor.id);
  const stored = await factory.extraction(documents.w9.id, "admin");
  expect(stored.status).toBe("approved");
});
